<?php use yii\widgets\ActiveForm;use yii\helpers\Html;$this->title='Тикет #'.$ticket->id;?><div class="card p-4"><div class="d-flex justify-content-between"><h2><?= Html::encode($ticket->subject) ?></h2><span><?= Html::encode($ticket->status) ?></span></div><?php foreach($ticket->messages as $msg):?><div class="border rounded p-3 my-2"><div class="small text-secondary"><?= $msg->is_staff?'STAFF':Html::encode($msg->author?->username ?: 'user') ?> · <?= Html::encode($msg->created_at) ?></div><?= nl2br(Html::encode($msg->body)) ?><?php if($msg->attachments):?><div class="mt-2"><?php foreach($msg->attachments as $a):?><?= Html::a(Html::encode($a->original_name),['attachment','id'=>$a->id],['class'=>'small me-2']) ?><?php endforeach;?></div><?php endif;?></div><?php endforeach;?><?php $f=ActiveForm::begin();echo $f->field($model,'message')->textarea(['rows'=>5]);echo Html::submitButton('Ответить',['class'=>'btn btn-primary']);ActiveForm::end();?><hr><?= Html::beginForm(['/support/close','id'=>$ticket->id],'post').Html::submitButton('Закрыть тикет',['class'=>'btn btn-outline-danger']).Html::endForm() ?></div>